\title{Finite-Perturbation Invariance and a Parity Obstruction\\for Strongly Complete Sets}
\author{Aristotle}
\date{August 1, 2026}

\begin{document}
\maketitle

\begin{abstract}
A set of nonnegative integers is complete if every sufficiently large integer is a sum of distinct elements of the set, and strongly complete if this remains true after every finite deletion. We develop the elementary structure of strong completeness and isolate the role of finite perturbations. Strong completeness implies completeness, is inherited after finite deletion, cannot be created by finite addition, and is invariant under finite symmetric difference. We then disprove the tempting converse from completeness to strong completeness. The set consisting of all even nonnegative integers together with $1$ represents every nonnegative integer as a sum of distinct elements, but deletion of $1$ leaves only even summands and excludes every odd target. This example identifies a modular single point of failure and shows why robust completeness requires distributional information beyond ordinary representability. We also present finite algorithms for enumerating subset sums and detecting deletion-induced residue obstructions, and discuss ordered-block, dyadic-density, and analytic divergence criteria.
\end{abstract}

\section{Introduction}

Given $A\subseteq\mathbb N$, subset-sum completeness asks whether every sufficiently large natural number is a finite sum of pairwise distinct elements of $A$. Strong completeness adds fault tolerance: after any finite collection of elements is removed, the surviving set must still represent every sufficiently large target.

One might expect finite deletion merely to shift the completeness threshold. This overlooks the possibility that finitely many exceptional summands carry entire congruence classes. Our central example is
\[
E=2\mathbb N\cup\{1\}.
\]
Every even target belongs to $E$, and every odd target at least $3$ is $1$ plus an even element. Yet removing $1$ leaves only even summands and makes every odd target impossible.

In contrast to ordinary completeness, strong completeness is a tail invariant. If two sets differ at only finitely many integers, either both are strongly complete or neither is. Thus finite elements can create completeness but cannot create its robust form.

\section{Definitions and preliminary principles}

Throughout, $\mathbb N=\{0,1,2,\ldots\}$, and all subset sums are finite.

\begin{definition}[Distinct subset-sum representation]
For $A\subseteq\mathbb N$ and $n\in\mathbb N$, the number $n$ is a \emph{distinct subset sum from $A$} if there is a finite set $S\subseteq A$ such that
\[
\sum_{a\in S}a=n.
\]
\end{definition}

\begin{definition}[Completeness]
A set $A\subseteq\mathbb N$ is \emph{complete} if there is $N\in\mathbb N$ such that every $n\ge N$ is a distinct subset sum from $A$.
\end{definition}

\begin{definition}[Strong completeness]
A set $A\subseteq\mathbb N$ is \emph{strongly complete} if $A\setminus F$ is complete for every finite set $F\subseteq\mathbb N$. The threshold may depend on $F$.
\end{definition}

\begin{proposition}
Every strongly complete set is complete.
\end{proposition}
\begin{proof}
Use the empty deletion: $A\setminus\varnothing=A$.
\end{proof}

\begin{lemma}[Upward monotonicity of completeness]
If $C\subseteq D\subseteq\mathbb N$ and $C$ is complete, then $D$ is complete.
\end{lemma}
\begin{proof}
Every representation using elements of $C$ is unchanged when regarded as a representation using elements of $D$.
\end{proof}

\section{Finite deletion and finite addition}

\begin{theorem}[Closure under finite deletion]
If $A$ is strongly complete and $F$ is finite, then $A\setminus F$ is strongly complete.
\end{theorem}
\begin{proof}
For any finite $G$,
\[
(A\setminus F)\setminus G=A\setminus(F\cup G).
\]
The union is finite, so the right-hand side is complete by strong completeness of $A$.
\end{proof}

\begin{theorem}[Finite addition cannot create strong completeness]
Let $F$ be finite. If $A\cup F$ is strongly complete, then $A$ is strongly complete.
\end{theorem}
\begin{proof}
Fix a finite set $G$. Delete $G\cup F$ from $A\cup F$. The resulting complete set satisfies
\[
(A\cup F)\setminus(G\cup F)\subseteq A\setminus G.
\]
Upward monotonicity makes $A\setminus G$ complete. Since $G$ was arbitrary, $A$ is strongly complete.
\end{proof}

\begin{proposition}[Upward monotonicity of strong completeness]
If $A\subseteq B$ and $A$ is strongly complete, then $B$ is strongly complete.
\end{proposition}
\begin{proof}
For finite $F$, the complete set $A\setminus F$ is contained in $B\setminus F$; apply upward monotonicity of completeness.
\end{proof}

\section{Finite-perturbation invariance}

\begin{definition}[Symmetric difference]
For $A,B\subseteq\mathbb N$, define
\[
A\mathbin{\triangle}B=(A\setminus B)\cup(B\setminus A).
\]
\end{definition}

\begin{theorem}[Finite-perturbation invariance]
If $A\mathbin{\triangle}B$ is finite, then $A$ is strongly complete if and only if $B$ is strongly complete.
\end{theorem}
\begin{proof}
Assume $A$ is strongly complete and let $G$ be finite. Since $A\setminus B$ is finite, strong completeness of $A$ makes
\[
A\setminus\bigl(G\cup(A\setminus B)\bigr)=(A\cap B)\setminus G
\]
complete. This common remainder is contained in $B\setminus G$, which is complete by upward monotonicity. Hence $B$ is strongly complete. Interchanging $A$ and $B$ proves the converse, using finiteness of $B\setminus A$.
\end{proof}

\begin{corollary}
For finite $F$, the sets $A$, $A\cup F$, and $A\setminus F$ are either all strongly complete or all not strongly complete.
\end{corollary}
\begin{proof}
Each pair differs by at most the finite set $F$.
\end{proof}

\section{A parity obstruction}

\begin{definition}
Let
\[
E=2\mathbb N\cup\{1\}.
\]
\end{definition}

\begin{theorem}[Completeness of the parity example]
Every $n\in\mathbb N$ is a distinct subset sum from $E$.
\end{theorem}
\begin{proof}
If $n$ is even, use the singleton $\{n\}$. If $n\ge3$ is odd, then
\[
n=1+(n-1),
\]
where $n-1$ is even and differs from $1$. The value $1$ is represented by $\{1\}$, and $0$ by the empty set or $\{0\}$. Thus $E$ is complete with threshold $0$.
\end{proof}

\begin{lemma}[Parity closure]
Every finite sum of even natural numbers is even.
\end{lemma}
\begin{proof}
The empty sum is even, and adding an even term preserves evenness. Induct on the number of summands.
\end{proof}

\begin{theorem}[Completeness does not imply strong completeness]
The set $E$ is complete but not strongly complete.
\end{theorem}
\begin{proof}
Completeness was just proved. Delete $\{1\}$. Every surviving element is even, so every finite subset sum is even. For any proposed threshold $N$, the odd integer $2N+1$ is at least $N$ and cannot be represented. Thus $E\setminus\{1\}$ is not complete.
\end{proof}

\begin{remark}[Modular template]
Parity is the modulus-$2$ instance of a general obstruction. If finite deletion leaves all available elements in a proper additive subgroup of $\mathbb Z/m\mathbb Z$, then every subset sum remains in that subgroup. Excluded residue classes contain arbitrarily large integers, so the remainder is not complete.
\end{remark}

\section{Algorithms and numerical demonstrations}

\subsection{Bounded distinct subset sums}

For a finite set $V$ and bound $T$, initialize $R=\{0\}$. For each $a\in V$, replace $R$ by
\[
R\cup\{r+a:r\in R,\ r+a\le T\},
\]
using the pre-update $R$ so that $a$ is used at most once. A Boolean-array implementation requires $O(|V|T)$ time and $O(T)$ space.

For
\[
E_M=\{0,2,4,\ldots,M\}\cup\{1\},
\]
the reachable values fill a long initial interval. Removing $1$ leaves exactly even reachable sums within the computed range, displaying the invariant behind the theorem.

\subsection{Deletion stress testing}

For each candidate deletion $F$, compute bounded subset sums from $V\setminus F$, list newly missing targets, and classify them modulo small integers. Exhaustive testing of deletions of size at most $d$ requires
\[
\sum_{j=0}^{d}\binom{|V|}{j}
\]
subset-sum runs. This is practical for small fixed $d$ and can reveal indispensable elements or modular patterns, though no finite experiment proves strong completeness of an arbitrary infinite set.

\subsection{Direct representations}

The positive representation theorem has the constant-size constructor
\[
S(n)=
\begin{cases}
\{n\},&n\text{ even},\\
\{1\},&n=1,\\
\{1,n-1\},&n\ge3\text{ odd}.
\end{cases}
\]
Every output consists of distinct elements of $E$ and sums to $n$.

\section{Toward stronger criteria}

\subsection{Density across scales}

Define the dyadic block
\[
D_k(A)=A\cap(2^k,2^{k+1}].
\]
Lower bounds on $|D_k(A)|$ for all sufficiently large $k$ guarantee recurring summands at every scale. Such supply conditions prevent uncontrolled deserts, but the parity example warns that numerical supply must be combined with arithmetic distribution.

\subsection{Distance to the nearest integer}

For $x\in\mathbb R$, let
\[
\|x\|=\min_{z\in\mathbb Z}|x-z|.
\]
Divergence conditions involving
\[
\sum_{a\in A}\|a\theta\|
\]
for each nonintegral $\theta$ measure resistance to arithmetic alignment. Scale density supplies pieces of suitable magnitude, while distributional conditions are intended to rule out modular or near-modular collapse. No such analytic criterion is proved here; these hypotheses describe the natural next layer beyond the foundational structural results.

\subsection{Ordered blocks}

A flexible approach uses finite blocks $B_0,B_1,\ldots$ with
\[
\max B_k<\min B_{k+1}.
\]
A prospective criterion would combine lower bounds on $|A\cap B_k|$ with overlap conditions for successive attainable subset-sum intervals. The structure separates local combinatorial richness, geometric ordering, and control of gaps. Eventual conditions with sufficient slack are natural candidates for persistence under finite deletion.

\section{Applications and interpretation}

Completeness is availability: every large demand can be assembled. Strong completeness is reliability: availability remains after finitely many component failures. The parity example is a mathematical single point of failure. It has abundant even components, but all access to odd outputs passes through one element.

Finite-perturbation invariance permits classification modulo finite symmetric difference. Initial irregularities can be removed and finite conveniences added without changing strong completeness. Ordinary completeness behaves differently: $2\mathbb N$ and $2\mathbb N\cup\{1\}$ differ by one element, yet the former misses all odd numbers and the latter represents every number.

The example also gives a counterexample-design method: begin with a core whose sums are trapped in selected residue classes, add finitely many bridge elements to obtain ordinary completeness, and then remove those bridges to expose the obstruction.

\section{Discussion and future work}

An ordered-block criterion should be developed before a dyadic specialization. Its assumptions should express pairwise ordered finite blocks, lower cardinality bounds, and overlap among attainable intervals. The dyadic blocks $D_k(A)$ can then be checked against these abstract conditions.

A careful treatment of analytic divergence should use an order-independent nonnegative sum indexed by a set. Another useful reduction is to canonical initial-segment deletions. Every finite $F$ is contained in $\{0,1,\ldots,M\}$ for some $M$; if deleting the entire initial segment leaves a complete subset, upward monotonicity gives completeness after deleting $F$. Thus strong completeness should be characterizable using only finite initial segments.

Further contrarian questions include whether completeness plus infinitely many odd elements implies strong completeness, whether infinite occupation of every residue class modulo every $m\ge2$ suffices, and whether stronger quantitative distribution permits weaker block-cardinality assumptions. Parity is only the simplest obstruction, so larger moduli and scale--congruence interactions merit systematic study.

\section{Conclusion}

Strong completeness measures whether subset-sum coverage is distributed throughout an infinite set rather than routed through finitely many exceptional summands. The set $2\mathbb N\cup\{1\}$ represents every nonnegative integer, yet deleting $1$ eliminates all odd sums. Completeness therefore does not imply strong completeness.

Conversely, genuine strong completeness has exact finite-perturbation stability: it survives finite deletion, cannot be created by finite addition, and is unchanged when two sets differ finitely. These results establish the appropriate structural foundation for future criteria based on ordered blocks, dyadic scale density, and analytic distribution.

\end{document}

