from __future__ import annotations
from typing import Iterable

def bounded_distinct_subset_sums(values: Iterable[int], target_bound: int) -> set[int]:
    """Return all sums at most target_bound using each input value at most once."""
    if target_bound < 0:
        raise ValueError("target_bound must be nonnegative")
    items = sorted(set(values))
    if any(value < 0 for value in items):
        raise ValueError("values must be nonnegative")
    reachable = {0}
    for value in items:
        snapshot = tuple(reachable)
        reachable.update(total + value for total in snapshot
                         if total + value <= target_bound)
    return reachable

from __future__ import annotations
from itertools import combinations
from typing import Iterable

def reachable(values: Iterable[int], bound: int) -> set[int]:
    totals = {0}
    for value in sorted(set(values)):
        old = tuple(totals)
        totals.update(x + value for x in old if x + value <= bound)
    return totals

def deletion_stress_test(values: Iterable[int], bound: int, budget: int = 1) -> list[dict[str, object]]:
    """Rank deletions by the number of bounded targets they make unreachable."""
    items = tuple(sorted(set(values)))
    baseline = reachable(items, bound)
    reports: list[dict[str, object]] = []
    for size in range(1, min(budget, len(items)) + 1):
        for deleted in combinations(items, size):
            survivors = (x for x in items if x not in deleted)
            lost = sorted(baseline - reachable(survivors, bound))
            reports.append({"deleted": deleted, "lost": lost, "loss_count": len(lost)})
    return sorted(reports, key=lambda report: int(report["loss_count"]), reverse=True)

